import{_ as t,c as a,a2 as o,o as i}from"./chunks/framework.CoXjB5sU.js";const m=JSON.parse(`{"title":"I can't choose a community when publishing","description":"","frontmatter":{"prev":{"text":"Can't log in with the shell client","link":"/doc/faqs/general/shell-bad-password"},"next":{"text":"Administration FAQs","link":"/doc/faqs/administration"}},"headers":[],"relativePath":"doc/faqs/general/create-publish-error.md","filePath":"doc/faqs/general/create-publish-error.md"}`),n={name:"doc/faqs/general/create-publish-error.md"};function r(s,e,c,l,h,u){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="i-can-t-choose-a-community-when-publishing" tabindex="-1">I can&#39;t choose a community when publishing <a class="header-anchor" href="#i-can-t-choose-a-community-when-publishing" aria-label="Permalink to &quot;I can&#39;t choose a community when publishing&quot;">​</a></h1><p>When you publish a project from Create, the publication dialog lists the Browse communities you can publish into. If the list is empty, your account has no publishing community yet.</p><p>Users publish into the publishing community of their user groups. Contact your ioChem-BD administrator and ask them to:</p><ol><li><a href="./../../guides/installation/publishing-endpoints-definition.html#community-generation">create a community</a> for your research group, if it doesn&#39;t exist yet, and</li><li>link it to your <a href="./../../guides/installation/user-and-group-generation.html#creating-groups">user group</a>, or add you to a group that already has it.</li></ol><p>The change applies at once: open the publication dialog again.</p><p>If instead the message <em>There has been an error retrieving Browse collection structure</em> appears, Create could not read the Browse communities. Send the full message to your administrator, who can check the Tomcat log (<em>apache-tomcat/logs/catalina.out</em>).</p>',6)]))}const d=t(n,[["render",r]]);export{m as __pageData,d as default};
